/* capture.c -- see capture.h. Plain libwayland-client; the protocol code
 * (wlr-screencopy-unstable-v1) is generated by wayland-scanner at build time. */
#include "capture.h"
#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <time.h>
#include <unistd.h>
#include <wayland-client.h>
#include "wlr-screencopy-unstable-v1-client-protocol.h"

#define FOURCC(a, b, c, d) ((uint32_t)(a) | ((uint32_t)(b) << 8) | ((uint32_t)(c) << 16) | ((uint32_t)(d) << 24))

struct cap {
  struct wl_display *dpy;
  struct wl_shm *shm;
  struct zwlr_screencopy_manager_v1 *mgr;
  struct wl_output *outputs[16];
  int n_outputs;
  /* the shm buffer, made again when the output's size or format changes */
  struct wl_buffer *buf;
  uint8_t *map;
  size_t map_len;
  uint32_t format, width, height, stride;
  /* the frame being copied */
  uint32_t f_format, f_width, f_height, f_stride;
  int have_shm, y_invert, done, failed;
  capture_cb cb;
  void *user;
};

static int shm_file(size_t len) {
  char name[64];
  for (int i = 0; i < 100; i++) {
    snprintf(name, sizeof name, "/screencast-%d-%d", (int)getpid(), i);
    int fd = shm_open(name, O_RDWR | O_CREAT | O_EXCL, 0600);
    if (fd >= 0) {
      shm_unlink(name);
      if (ftruncate(fd, (off_t)len) == 0) return fd;
      close(fd);
      return -1;
    }
    if (errno != EEXIST) return -1;
  }
  return -1;
}

static int make_buffer(struct cap *c) {
  if (c->buf && c->format == c->f_format && c->width == c->f_width &&
      c->height == c->f_height && c->stride == c->f_stride)
    return 0;
  if (c->buf) { wl_buffer_destroy(c->buf); c->buf = NULL; }
  if (c->map) { munmap(c->map, c->map_len); c->map = NULL; }
  size_t len = (size_t)c->f_stride * c->f_height;
  int fd = shm_file(len);
  if (fd < 0) { perror("screencast: shared memory"); return -1; }
  void *p = mmap(NULL, len, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
  if (p == MAP_FAILED) { perror("screencast: mmap"); close(fd); return -1; }
  struct wl_shm_pool *pool = wl_shm_create_pool(c->shm, fd, (int32_t)len);
  c->buf = wl_shm_pool_create_buffer(pool, 0, (int32_t)c->f_width, (int32_t)c->f_height,
                                     (int32_t)c->f_stride, c->f_format);
  wl_shm_pool_destroy(pool);
  close(fd);
  c->map = p; c->map_len = len;
  c->format = c->f_format; c->width = c->f_width; c->height = c->f_height; c->stride = c->f_stride;
  return 0;
}

static void f_buffer(void *d, struct zwlr_screencopy_frame_v1 *f, uint32_t format,
                     uint32_t w, uint32_t h, uint32_t stride) {
  struct cap *c = d; (void)f;
  /* several formats may be offered: keep the first 32-bit one */
  if (c->have_shm) return;
  switch (format) {
  case WL_SHM_FORMAT_XRGB8888: case WL_SHM_FORMAT_ARGB8888:
  case WL_SHM_FORMAT_XBGR8888: case WL_SHM_FORMAT_ABGR8888:
    c->f_format = format; c->f_width = w; c->f_height = h; c->f_stride = stride; c->have_shm = 1;
  }
}
static void f_flags(void *d, struct zwlr_screencopy_frame_v1 *f, uint32_t flags) {
  struct cap *c = d; (void)f;
  c->y_invert = (flags & ZWLR_SCREENCOPY_FRAME_V1_FLAGS_Y_INVERT) != 0;
}
static void f_ready(void *d, struct zwlr_screencopy_frame_v1 *f, uint32_t hi, uint32_t lo, uint32_t ns) {
  struct cap *c = d; (void)f; (void)hi; (void)lo; (void)ns;
  c->done = 1;
}
static void f_failed(void *d, struct zwlr_screencopy_frame_v1 *f) {
  struct cap *c = d; (void)f;
  c->done = 1; c->failed = 1;
}
static void f_damage(void *d, struct zwlr_screencopy_frame_v1 *f, uint32_t x, uint32_t y, uint32_t w, uint32_t h) {
  (void)d; (void)f; (void)x; (void)y; (void)w; (void)h;
}
static void f_dmabuf(void *d, struct zwlr_screencopy_frame_v1 *f, uint32_t fmt, uint32_t w, uint32_t h) {
  (void)d; (void)f; (void)fmt; (void)w; (void)h;
}
static void f_buffer_done(void *d, struct zwlr_screencopy_frame_v1 *f) {
  struct cap *c = d;
  if (!c->have_shm || make_buffer(c) != 0) { c->done = 1; c->failed = 1; return; }
  zwlr_screencopy_frame_v1_copy(f, c->buf);
}
static const struct zwlr_screencopy_frame_v1_listener frame_listener = {
  .buffer = f_buffer, .flags = f_flags, .ready = f_ready, .failed = f_failed,
  .damage = f_damage, .linux_dmabuf = f_dmabuf, .buffer_done = f_buffer_done,
};

static void reg_global(void *d, struct wl_registry *r, uint32_t name, const char *iface, uint32_t ver) {
  struct cap *c = d;
  if (!strcmp(iface, wl_shm_interface.name))
    c->shm = wl_registry_bind(r, name, &wl_shm_interface, 1);
  else if (!strcmp(iface, wl_output_interface.name) && c->n_outputs < 16)
    c->outputs[c->n_outputs++] = wl_registry_bind(r, name, &wl_output_interface, 1);
  else if (!strcmp(iface, zwlr_screencopy_manager_v1_interface.name))
    /* version 3 adds buffer_done; with 1 and 2 the copy starts at "buffer" */
    c->mgr = wl_registry_bind(r, name, &zwlr_screencopy_manager_v1_interface, ver < 3 ? ver : 3);
}
static void reg_remove(void *d, struct wl_registry *r, uint32_t name) { (void)d; (void)r; (void)name; }
static const struct wl_registry_listener reg_listener = { reg_global, reg_remove };

static int64_t now_ms(void) {
  struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
  return (int64_t)t.tv_sec * 1000 + t.tv_nsec / 1000000;
}

int capture_run(const char *display, int output, int fps, int cursor,
                capture_cb cb, void *user, volatile int *stop) {
  struct cap c; memset(&c, 0, sizeof c);
  c.cb = cb; c.user = user;
  c.dpy = wl_display_connect(display);
  if (!c.dpy) {
    fprintf(stderr, "screencast: cannot connect to the Wayland display %s (is the desktop running? XDG_RUNTIME_DIR=%s)\n",
            display ? display : "(WAYLAND_DISPLAY)", getenv("XDG_RUNTIME_DIR") ? getenv("XDG_RUNTIME_DIR") : "unset");
    return -1;
  }
  struct wl_registry *reg = wl_display_get_registry(c.dpy);
  wl_registry_add_listener(reg, &reg_listener, &c);
  wl_display_roundtrip(c.dpy);
  if (!c.shm || !c.mgr || output >= c.n_outputs) {
    fprintf(stderr, "screencast: the compositor has %s\n",
            !c.mgr ? "no wlr-screencopy (zwlr_screencopy_manager_v1)" : !c.shm ? "no wl_shm" : "no such output");
    wl_display_disconnect(c.dpy);
    return -1;
  }
  if (fps < 1) fps = 1;
  int rc = 0, fails = 0, wait_ms = 0;
  int ver = (int)zwlr_screencopy_manager_v1_get_version(c.mgr);
  while (!*stop) {
    int64_t t0 = now_ms();
    c.done = c.failed = c.have_shm = c.y_invert = 0;
    struct zwlr_screencopy_frame_v1 *f =
        zwlr_screencopy_manager_v1_capture_output(c.mgr, cursor, c.outputs[output]);
    zwlr_screencopy_frame_v1_add_listener(f, &frame_listener, &c);
    if (ver < 3) {  /* no buffer_done: wait for "buffer", then copy */
      while (!c.have_shm && !c.done && wl_display_dispatch(c.dpy) != -1) {}
      if (c.have_shm && !c.done) f_buffer_done(&c, f);
    }
    while (!c.done && !*stop) {
      if (wl_display_dispatch(c.dpy) == -1) { rc = -1; break; }
    }
    zwlr_screencopy_frame_v1_destroy(f);
    if (rc) { fprintf(stderr, "screencast: the Wayland connection was lost\n"); break; }
    if (*stop) break;
    if (c.failed) {
      if (++fails > 50) { fprintf(stderr, "screencast: the compositor keeps refusing the copy\n"); rc = -1; break; }
    } else {
      fails = 0;
      struct capture_frame fr = { c.map, (int)c.width, (int)c.height, (int)c.stride, 0, c.y_invert };
      /* wl_shm formats are little-endian words: XRGB8888 is B,G,R,X in memory */
      fr.fourcc = (c.format == WL_SHM_FORMAT_XBGR8888 || c.format == WL_SHM_FORMAT_ABGR8888)
                      ? FOURCC('A', 'B', 'G', 'R') : FOURCC('A', 'R', 'G', 'B');
      wait_ms = cb(user, &fr);
    }
    int64_t left = (wait_ms > 0 ? wait_ms : 1000 / fps) - (now_ms() - t0);
    if (left > 0) { struct timespec ts = { left / 1000, (left % 1000) * 1000000L }; nanosleep(&ts, NULL); }
  }
  if (c.buf) wl_buffer_destroy(c.buf);
  if (c.map) munmap(c.map, c.map_len);
  wl_display_disconnect(c.dpy);
  return rc;
}
